content.solution_code:
class Gadget {
    #batteryLevel;

    constructor(name, initialBattery) {
        this.name = name;
        this.#batteryLevel = Math.max(0, Math.min(100, initialBattery));
    }

    charge(amount) {
        if (amount <= 0) {
            console.log("Charge amount must be positive.");
            return;
        }
        this.#batteryLevel = Math.min(100, this.#batteryLevel + amount);
    }

    getBatteryLevel() {
        return this.#batteryLevel;
    }
}

class Smartphone extends Gadget {
    constructor(name, initialBattery, screenSize, os) {
        super(name, initialBattery);
        this.screenSize = screenSize;
        this.operatingSystem = os;
    }

    displayInfo() {
        return `${this.name} (Battery: ${this.getBatteryLevel()}%) - Screen: ${this.screenSize}in, OS: ${this.operatingSystem}`;
    }
}

class Smartwatch extends Gadget {
    constructor(name, initialBattery, strapMaterial, hasHRMonitor) {
        super(name, initialBattery);
        this.strapMaterial = strapMaterial;
        this.hasHRMonitor = hasHRMonitor;
    }

    displayInfo() {
        const hrStatus = this.hasHRMonitor ? "Yes" : "No";
        return `${this.name} (Battery: ${this.getBatteryLevel()}%) - Strap: ${this.strapMaterial}, HR Monitor: ${hrStatus}`;
    }
}

